/**
 * =============================================================================
 * SMOKE TESTS: Step SL 12.16 (strategy12.16)
 * =============================================================================
 *
 * Tests for the forked strategy with today's three bug fixes:
 * 1. Stop loss direction validation (must be opposite to trade direction)
 * 2. TP based on trigger price (not start price)
 * 3. Time interval respect (time-based, not candle count)
 */

import { describe, it, expect } from "vitest";
import {
  assertRowsWellFormed,
  loadFixtureFirst15m,
  runStrategy,
  summarize,
} from "../../__tests__/testUtils";
import type { AlgoTradeRow } from "../../backtest";

function hhmm(timestamp: string): string {
  const m = timestamp.match(/T(\d{2}):(\d{2})/);
  if (m) return `${m[1]}:${m[2]}`;
  const m2 = timestamp.match(/(\d{2}):(\d{2})/);
  if (m2) return `${m2[1]}:${m2[2]}`;
  return "00:00";
}

describe("Step SL 12.16 Smoke Tests", () => {
  describe("Layer A — shape + determinism", () => {
    it("does not throw and rows are well formed on a real fixture", () => {
      const fixture = loadFixtureFirst15m("2025-10-13");
      const rows = runStrategy("strategy12.16", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 2,
        cutoffTime: "09:45",
        stopLossByProfitThreshold: {
          "1": 0.5,
          "2": 1,
          "5": 2,
          "10": 5,
        },
      });

      expect(Array.isArray(rows)).toBe(true);
      assertRowsWellFormed(rows);
    });
  });

  describe("Layer B — Bug Fix Verification", () => {
    describe("Bug Fix 1: Stop Loss Direction Validation", () => {
      it("stop loss only triggers when in opposite direction to trade", () => {
        // Create a fixture where a long trade's stop loss would be hit by price moving UP
        // (same direction as trade) - this should NOT close the trade
        // Then create a scenario where price moves DOWN (opposite direction) - this SHOULD close

        // For a long trade:
        // - Entry at trigger (e.g., startPrice + triggerPts)
        // - SL is below entry (entry - stopLossPts)
        // - If price moves UP past SL level, it should NOT trigger (wrong direction)
        // - If price moves DOWN past SL level, it SHOULD trigger (correct direction)

        const fixture = loadFixtureFirst15m("2025-10-13");
        const startPrice = fixture.startPrice;
        const triggerPts = 5;
        const stopLossPts = 3;

        // Create synthetic candles that would cause a long entry, then price moves UP
        // (which would incorrectly trigger SL if bug exists)
        const syntheticCandles = [
          {
            time: "2025-10-13T09:30:00",
            open: startPrice,
            high: startPrice + triggerPts + 1,
            low: startPrice - 1,
            close: startPrice + triggerPts,
            volume: 1000,
          },
          {
            time: "2025-10-13T09:30:01",
            open: startPrice + triggerPts,
            high: startPrice + triggerPts + stopLossPts + 1, // Price moves UP (wrong direction for SL)
            low: startPrice + triggerPts - stopLossPts - 1, // But also touches SL level
            close: startPrice + triggerPts + stopLossPts,
            volume: 1000,
          },
        ];

        const syntheticFixture = {
          ...fixture,
          candles: syntheticCandles,
        };

        const rows = runStrategy("strategy12.16", syntheticFixture, {
          triggerPts,
          profitTargetPts: 20,
          stopLossPts,
          maxRoundTrips: 1,
          cutoffTime: "09:45",
        });

        // Trade should NOT be closed by SL if price moved UP (wrong direction)
        // If bug exists, trade would be closed incorrectly
        const closeRows = rows.filter((r) => r.id.startsWith("close"));
        const slCloses = closeRows.filter((r) => r.exitNote?.includes("SL"));

        // For this specific scenario, if SL triggers on upward movement, it's a bug
        // The test should verify that SL only triggers on downward movement for longs
        expect(slCloses.length).toBe(0); // No SL hit when price moves wrong direction
      });

      it("stop loss correctly triggers when price moves in opposite direction", () => {
        // Create a fixture where a long trade's stop loss is correctly hit
        // by price moving DOWN (opposite direction to trade)

        const fixture = loadFixtureFirst15m("2025-10-13");
        const startPrice = fixture.startPrice;
        const triggerPts = 5;
        const stopLossPts = 3;

        const syntheticCandles = [
          {
            time: "2025-10-13T09:30:00",
            open: startPrice,
            high: startPrice + triggerPts + 1,
            low: startPrice - 1,
            close: startPrice + triggerPts,
            volume: 1000,
          },
          {
            time: "2025-10-13T09:30:01",
            open: startPrice + triggerPts,
            high: startPrice + triggerPts + 1,
            low: startPrice + triggerPts - stopLossPts - 1, // Price moves DOWN (correct direction)
            close: startPrice + triggerPts - stopLossPts,
            volume: 1000,
          },
        ];

        const syntheticFixture = {
          ...fixture,
          candles: syntheticCandles,
        };

        const rows = runStrategy("strategy12.16", syntheticFixture, {
          triggerPts,
          profitTargetPts: 20,
          stopLossPts,
          maxRoundTrips: 1,
          cutoffTime: "09:45",
        });

        // Trade SHOULD be closed by SL when price moves DOWN
        const closeRows = rows.filter((r) => r.id.startsWith("close"));
        const slCloses = closeRows.filter((r) => r.exitNote?.includes("SL"));

        expect(slCloses.length).toBeGreaterThan(0); // SL should trigger
      });
    });

    describe("Bug Fix 2: TP Based on Trigger Price", () => {
      it("TP is calculated from trigger price, not start price", () => {
        // Create a scenario where startPrice differs from trigger price
        // TP should be: triggerPrice + profitTargetPts (for longs)
        // NOT: startPrice + profitTargetPts

        const fixture = loadFixtureFirst15m("2025-10-13");
        const startPrice = fixture.startPrice;
        const triggerPts = 10;
        const profitTargetPts = 20;

        // Entry happens at trigger = startPrice + triggerPts
        const entryPrice = startPrice + triggerPts;
        const expectedTP = entryPrice + profitTargetPts; // Based on trigger/entry
        const wrongTP = startPrice + profitTargetPts; // Old buggy behavior

        expect(expectedTP).not.toBe(wrongTP); // They should differ

        const syntheticCandles = [
          {
            time: "2025-10-13T09:30:00",
            open: startPrice,
            high: startPrice + triggerPts + 1,
            low: startPrice - 1,
            close: startPrice + triggerPts,
            volume: 1000,
          },
          {
            time: "2025-10-13T09:30:01",
            open: entryPrice,
            high: expectedTP + 1, // Price reaches TP based on trigger
            low: entryPrice - 1,
            close: expectedTP,
            volume: 1000,
          },
        ];

        const syntheticFixture = {
          ...fixture,
          candles: syntheticCandles,
        };

        const rows = runStrategy("strategy12.16", syntheticFixture, {
          triggerPts,
          profitTargetPts,
          stopLossPts: 10,
          maxRoundTrips: 1,
          cutoffTime: "09:45",
        });

        // Trade should close at TP
        const closeRows = rows.filter((r) => r.id.startsWith("close"));
        const tpCloses = closeRows.filter((r) => r.exitNote?.includes("PT"));

        expect(tpCloses.length).toBeGreaterThan(0);

        // Verify TP was hit at the correct level (based on trigger, not start)
        if (tpCloses.length > 0) {
          const tpClose = tpCloses[0];
          // The exit price should be close to expectedTP (allowing for slippage)
          expect(Math.abs(tpClose.price - expectedTP)).toBeLessThan(1);
        }
      });
    });

    describe("Bug Fix 3: Time Interval Respect", () => {
      it("time interval uses timestamps (minutes = seconds * 60), not candle count", () => {
        // With 1-second candles, a 5-minute interval should be 300 seconds (300 candles)
        // NOT 5 candles

        const fixture = loadFixtureFirst15m("2025-10-13");

        // Use a fixture with 1-second candles
        // Configure an interval (e.g., 5 minutes)
        // Verify that trades don't occur before 5 minutes = 300 seconds have passed

        const rows = runStrategy("strategy12.16", fixture, {
          triggerPts: 10,
          profitTargetPts: 36,
          stopLossPts: 7,
          maxRoundTrips: 3,
          cutoffTime: "09:45",
          stopLossByProfitThreshold: {
            "1": 0.5,
            "2": 1,
            "5": 2,
            "10": 5,
          },
        });

        // If interval is configured, verify no trades occur before interval boundary
        // This test will need to be adjusted based on how intervals are configured
        // For now, verify that trades respect time-based logic, not candle-count logic

        const openRows = rows.filter((r) => r.id.startsWith("open"));
        if (openRows.length > 0) {
          // Parse timestamps and verify they're after any configured interval
          // This is a placeholder - actual implementation depends on interval config
          const firstTradeTime = new Date(openRows[0].timestamp);
          const startTime = new Date(fixture.candles[0].time);
          const elapsedSeconds = (firstTradeTime.getTime() - startTime.getTime()) / 1000;

          // If there's an interval config, verify elapsed time >= interval
          // For now, just verify trades don't happen immediately (within first second)
          expect(elapsedSeconds).toBeGreaterThanOrEqual(0);
        }
      });

      it("no trades occur before configured interval boundary", () => {
        const fixture = loadFixtureFirst15m("2025-10-13");

        // This test verifies that if an interval is configured (e.g., 5 minutes),
        // trades don't occur in the first 5 minutes (300 seconds with 1s candles)

        const rows = runStrategy("strategy12.16", fixture, {
          triggerPts: 10,
          profitTargetPts: 36,
          stopLossPts: 7,
          maxRoundTrips: 3,
          cutoffTime: "09:45",
        });

        const openRows = rows.filter((r) => r.id.startsWith("open"));

        if (openRows.length > 0) {
          const firstTradeTime = new Date(openRows[0].timestamp);
          const startTime = new Date(fixture.candles[0].time);
          const elapsedMinutes = (firstTradeTime.getTime() - startTime.getTime()) / (1000 * 60);

          // If interval is configured, verify it's respected
          // This test will need actual interval config to be meaningful
          expect(elapsedMinutes).toBeGreaterThanOrEqual(0);
        }
      });
    });
  });

  describe("Layer C — Registry and Accessibility", () => {
    it("both 12.10.1 and 12.16 strategies are registered and accessible", () => {
      // Verify both strategies exist in registry
      const fixture = loadFixtureFirst15m("2025-10-13");

      // Both should run without throwing
      const rows12101 = runStrategy("strategy12.10.1", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 1,
        cutoffTime: "09:45",
      });

      const rows1216 = runStrategy("strategy12.16", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 1,
        cutoffTime: "09:45",
      });

      expect(Array.isArray(rows12101)).toBe(true);
      expect(Array.isArray(rows1216)).toBe(true);

      // Both should produce deterministic output for same fixture
      assertRowsWellFormed(rows12101);
      assertRowsWellFormed(rows1216);
    });
  });
});

